BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM `trade-analytics-508604.trade_analytics_published.batch_inputs` WHERE candidate_batch_id=@run_id) THEN
 INSERT INTO `trade-analytics-508604.trade_analytics_published.candidate_batches`
 SELECT c.*,@run_id FROM `trade-analytics-508604.trade_analytics_day10_dev.mart_us_semiconductor_supply_chain_candidate` c WHERE period_start_date=PARSE_DATE('%Y%m',@period) AND cmd_code=@cmd_code AND hs_version=@hs_version;
 INSERT INTO `trade-analytics-508604.trade_analytics_published.batch_inputs`
 SELECT @run_id,@period,@cmd_code,@hs_version,
 TO_JSON_STRING(STRUCT(
  ARRAY(SELECT AS STRUCT c.* EXCEPT(candidate_batch_id) FROM `trade-analytics-508604.trade_analytics_published.candidate_batches` c WHERE
 candidate_batch_id=@run_id) AS candidate,
  ARRAY(SELECT AS STRUCT * FROM `trade-analytics-508604.trade_raw.un_comtrade_partner_detail` WHERE
 period_start_date=PARSE_DATE('%Y%m',@period) AND cmd_code=@cmd_code AND hs_version=@hs_version) AS detail,
  ARRAY(SELECT AS STRUCT * FROM `trade-analytics-508604.trade_raw.un_comtrade_world_total` WHERE
 period_start_date=PARSE_DATE('%Y%m',@period) AND cmd_code=@cmd_code AND hs_version=@hs_version) AS world,
  ARRAY(SELECT PARSE_JSON(TO_JSON_STRING(a)) FROM `trade-analytics-508604.trade_raw.audit_ingestion_runs` a
        WHERE period=@period AND cmd_code=@cmd_code AND hs_version=@hs_version
        UNION ALL SELECT PARSE_JSON(attestation_json) FROM `trade-analytics-508604.trade_analytics_published.source_attestations`
        WHERE JSON_VALUE(attestation_json,'$.period')=@period) AS loads
  )),
 (SELECT TO_HEX(SHA256(COALESCE(STRING_AGG(TO_JSON_STRING(c),'\n' ORDER BY TO_JSON_STRING(c)),'')))
  FROM `trade-analytics-508604.trade_analytics_published.candidate_batches` c WHERE candidate_batch_id=@run_id),CURRENT_TIMESTAMP();
END IF;
COMMIT TRANSACTION;
SELECT * FROM `trade-analytics-508604.trade_analytics_published.batch_inputs` WHERE candidate_batch_id=@run_id;

BEGIN TRANSACTION;
ASSERT (SELECT COUNT(*)=1 FROM `trade-analytics-508604.trade_analytics_published.quality_audit_history` WHERE run_id=@run_id AND period=@period AND cmd_code=@cmd_code AND hs_version=@hs_version
 AND candidate_batch_id=@run_id AND status IN ('PASS','WARN')) AS 'gate_missing_or_failed';
ASSERT (SELECT COUNT(*)=1 FROM `trade-analytics-508604.trade_analytics_published.batch_inputs` WHERE candidate_batch_id=@run_id AND
 period=@period AND cmd_code=@cmd_code AND hs_version=@hs_version) AS 'batch_mismatch';
ASSERT (SELECT candidate_hash FROM `trade-analytics-508604.trade_analytics_published.quality_audit_history` WHERE run_id=@run_id) =
 (SELECT TO_HEX(SHA256(COALESCE(STRING_AGG(TO_JSON_STRING(c),'\n' ORDER BY TO_JSON_STRING(c)),'')))
 FROM `trade-analytics-508604.trade_analytics_published.candidate_batches` c WHERE candidate_batch_id=@run_id) AS 'candidate_changed';
ASSERT (SELECT COUNT(*)>0 AND COUNT(*)=COUNT(DISTINCT partner_code)
 AND COUNTIF(NOT (period=@period AND cmd_code=@cmd_code AND hs_version=@hs_version))=0
 FROM `trade-analytics-508604.trade_analytics_published.candidate_batches` WHERE candidate_batch_id=@run_id) AS 'candidate_grain';
IF NOT EXISTS(SELECT 1 FROM `trade-analytics-508604.trade_analytics_published.publication_attempts` WHERE run_id=@run_id AND
 publish_status='published') THEN
 ASSERT NOT EXISTS(
 SELECT 1 FROM `trade-analytics-508604.trade_analytics_published.quality_audit_history` a JOIN `trade-analytics-508604.trade_analytics_published.publication_attempts` p USING(run_id)
 WHERE a.period=@period AND a.cmd_code=@cmd_code AND a.hs_version=@hs_version AND
 p.publish_status='published'
 AND a.tested_at>(SELECT tested_at FROM `trade-analytics-508604.trade_analytics_published.quality_audit_history` WHERE run_id=@run_id)
 ) AS 'superseded_batch';
 DELETE FROM `trade-analytics-508604.trade_analytics_published.mart_us_semiconductor_supply_chain` WHERE period=@period AND cmd_code=@cmd_code AND hs_version=@hs_version;

 INSERT INTO `trade-analytics-508604.trade_analytics_published.mart_us_semiconductor_supply_chain`
 SELECT c.*,a.status,CURRENT_TIMESTAMP(),@run_id FROM `trade-analytics-508604.trade_analytics_published.candidate_batches` c
 JOIN `trade-analytics-508604.trade_analytics_published.quality_audit_history` a ON c.candidate_batch_id=a.run_id
 WHERE c.candidate_batch_id=@run_id;
 INSERT INTO `trade-analytics-508604.trade_analytics_published.publication_attempts`
 VALUES(@attempt_id,@run_id,@period,@cmd_code,@hs_version,'published',CURRENT_TIMESTAMP());
ELSE
 INSERT INTO `trade-analytics-508604.trade_analytics_published.publication_attempts`
 VALUES(@attempt_id,@run_id,@period,@cmd_code,@hs_version,'already_published',CURRENT_TIMESTAMP());
END IF;
COMMIT TRANSACTION;

